SELECT *
FROM (
    SELECT t.*, ROW_NUMBER() OVER (ORDER BY t.CREATED_TIME DESC, t.ID DESC) AS RN
    FROM (
        SELECT 
        FROM PROCUREMENT_DEMAND

            DELETED = 0

                AND STATUS = #{status}


                AND PROCUREMENT_NAME LIKE '%' || #{keyword} || '%'


    ) t
) page_data
WHERE RN > #{startRow} AND RN <= #{endRow}
ORDER BY RN

SELECT COUNT(1) FROM PROCUREMENT_DEMAND D WHERE D.DELETED = 0
AND (D.SOURCE_PROJECT_ID = #{materialId} OR EXISTS (
    SELECT 1 FROM PROCUREMENT_MATERIAL_LINK L
    WHERE L.DEMAND_ID = D.ID AND L.MATERIAL_ID = #{materialId}
) OR EXISTS (
    SELECT 1 FROM PROCUREMENT_DEMAND_MATERIAL L
    WHERE L.DEMAND_ID = D.ID AND L.MATERIAL_ID = #{materialId}
))

mapper.update:
UPDATE PROCUREMENT_DEMAND
SET STATUS = #{status}
WHERE ID = #{id} AND DELETED = 0
